from pathlib import Path
import json

app_path = Path('offline-interview/app.js')
s = app_path.read_text()
s = s.replace("2026-09-06.interview-runtime-v41.5", "2026-09-06.interview-runtime-v41.6", 1)

s = s.replace("let activeReplayAudio = null;\nlet activeReplayUrl = null;\nlet failedAudioCaptureIds = new Set();",
"let activeReplayAudio = null;\nlet activeReplayUrl = null;\nlet activeReplayTurnId = null;\nlet activeReplayButton = null;\nconst activeSystemRetranscriptions = new Set();\nlet failedAudioCaptureIds = new Set();", 1)

old = '''function stopReplay() {\n  try { activeReplayAudio?.pause(); } catch {}\n  activeReplayAudio = null;\n  if (activeReplayUrl) URL.revokeObjectURL(activeReplayUrl);\n  activeReplayUrl = null;\n}\n\nasync function replayTurnAudio(turn) {\n  const ref = turn?.audioRef;\n  if (!ref?.recordingId) return;\n  stopReplay();\n  const record = await dbAudioGet(ref.recordingId);\n  if (!record?.blob) { showError(ui.interviewError, 'Audio local introuvable pour cette prise de parole.'); return; }\n  const url = URL.createObjectURL(record.blob);\n  const audio = new Audio(url);\n  activeReplayAudio = audio; activeReplayUrl = url;\n  const end = Math.max(0, Number(ref.endMs) || 0) / 1000;\n  audio.addEventListener('loadedmetadata', () => { audio.currentTime = Math.max(0, Number(ref.startMs) || 0) / 1000; audio.play().catch(() => stopReplay()); }, { once: true });\n  audio.addEventListener('timeupdate', () => { if (end && audio.currentTime >= end) stopReplay(); });\n  audio.addEventListener('ended', stopReplay, { once: true });\n}\n'''
new = '''function updateReplayButton(button, playing) {\n  if (!button) return;\n  button.textContent = playing ? 'Ⅱ' : '▶';\n  button.title = playing ? 'Mettre cette prise en pause' : 'Réécouter cette prise de parole';\n  button.setAttribute('aria-label', button.title);\n  button.setAttribute('aria-pressed', playing ? 'true' : 'false');\n}\n\nfunction stopReplay() {\n  try { activeReplayAudio?.pause(); } catch {}\n  updateReplayButton(activeReplayButton, false);\n  activeReplayAudio = null;\n  activeReplayButton = null;\n  activeReplayTurnId = null;\n  if (activeReplayUrl) URL.revokeObjectURL(activeReplayUrl);\n  activeReplayUrl = null;\n}\n\nasync function replayTurnAudio(turn, button) {\n  const ref = turn?.audioRef;\n  if (!ref?.recordingId) return;\n  if (activeReplayTurnId === turn.id && activeReplayAudio) {\n    if (activeReplayAudio.paused) {\n      await activeReplayAudio.play();\n      updateReplayButton(activeReplayButton, true);\n    } else {\n      activeReplayAudio.pause();\n      updateReplayButton(activeReplayButton, false);\n    }\n    return;\n  }\n  stopReplay();\n  const record = await dbAudioGet(ref.recordingId);\n  if (!record?.blob) { showError(ui.interviewError, 'Audio local introuvable pour cette prise de parole.'); return; }\n  const url = URL.createObjectURL(record.blob);\n  const audio = new Audio(url);\n  activeReplayAudio = audio; activeReplayUrl = url; activeReplayTurnId = turn.id; activeReplayButton = button || null;\n  const end = Math.max(0, Number(ref.endMs) || 0) / 1000;\n  audio.addEventListener('loadedmetadata', () => {\n    audio.currentTime = Math.max(0, Number(ref.startMs) || 0) / 1000;\n    audio.play().then(() => updateReplayButton(activeReplayButton, true)).catch(() => stopReplay());\n  }, { once: true });\n  audio.addEventListener('timeupdate', () => { if (end && audio.currentTime >= end) stopReplay(); });\n  audio.addEventListener('ended', stopReplay, { once: true });\n}\n'''
if old not in s: raise SystemExit('replay block not found')
s = s.replace(old, new, 1)

start = s.index('async function retranscribeTurnWithSystem(turn, button) {')
end = s.index('\nfunction setView(name) {', start)
new_retranscribe = '''async function retranscribeTurnWithSystem(turn, button) {\n  showError(ui.interviewError, '');\n  const ref = turn?.audioRef;\n  const audioKey = ref?.recordingId ? `${ref.recordingId}:${Math.round(ref.startMs || 0)}:${Math.round(ref.endMs || 0)}` : null;\n  if (!audioKey) return;\n  const stable = turn.systemRetranscription;\n  if (stable?.audioKey === audioKey && ['succeeded', 'failed'].includes(stable.status)) {\n    showError(ui.interviewError, stable.status === 'succeeded'\n      ? 'Cette prise a déjà une retranscription système stabilisée. Le texte reste modifiable manuellement.'\n      : 'La tentative système de cette prise a déjà échoué. Le texte reste modifiable manuellement.');\n    return;\n  }\n  if (activeSystemRetranscriptions.has(audioKey)) return;\n  if (!supportsSystemAudioTrackRecognition()) {\n    showError(ui.interviewError, 'La retranscription système d’un enregistrement est disponible dans Chrome/Edge de bureau récents, mais pas encore dans les navigateurs mobiles. L’audio reste réécoutable et le texte modifiable.');\n    return;\n  }\n  if (systemSpeechCapability.mode === 'unavailable') {\n    showError(ui.interviewError, 'La transcription système n’est pas disponible dans ce navigateur.');\n    return;\n  }\n  activeSystemRetranscriptions.add(audioKey);\n  if (button) {\n    button.disabled = true;\n    button.textContent = '⏳ Système…';\n    button.classList.add('is-working');\n    button.setAttribute('aria-busy', 'true');\n  }\n  stopReplay();\n  let input = null;\n  try {\n    input = await buildTurnRecognitionTrack(turn);\n    const result = await transcribeSystemAudioTrack(input.track, {\n      lang: interview?.language || 'fr-FR',\n      mode: systemSpeechCapability.mode,\n      durationMs: input.durationMs,\n      onStart: () => input.start()\n    });\n    const text = cleanText(result?.text);\n    if (!meaningfulTranscript(text)) throw new Error('Aucun texte reconnu par le système pour cet extrait.');\n    if (!Array.isArray(turn.transcriptionHistory)) turn.transcriptionHistory = [];\n    if (cleanText(turn.text)) turn.transcriptionHistory.push({ text: turn.text, source: turn.source || null, at: nowIso() });\n    turn.text = text;\n    turn.rawTranscript = text;\n    turn.source = result.mode === 'local' ? 'system-local-retranscribed' : 'system-retranscribed';\n    turn.systemRetranscription = { audioKey, status: 'succeeded', text, mode: result.mode, at: nowIso() };\n    turn.updatedAt = nowIso();\n    session.updatedAt = nowIso();\n    logRuntimeEvent('system_retranscription_succeeded', { turnId: turn.id, mode: result.mode, stable: true });\n    persistSessionLater('system-retranscription');\n  } catch (error) {\n    turn.systemRetranscription = { audioKey, status: 'failed', error: String(error?.message || error), at: nowIso() };\n    recordRuntimeWarning('system_retranscription_error', error);\n    showError(ui.interviewError, `Retranscription système impossible : ${error.message || error}`);\n    persistSessionLater('system-retranscription-failed');\n  } finally {\n    activeSystemRetranscriptions.delete(audioKey);\n    input?.cleanup();\n    renderTurns();\n  }\n}\n'''
s = s[:start] + new_retranscribe + s[end:]

s = s.replace("  if (!systemSpeechSession?.cutSegment) return false;", "  if (!systemSpeechSession?.takeSegment) return false;", 1)
s = s.replace("  const cut = systemSpeechSession.cutSegment();", "  const cut = systemSpeechSession.takeSegment();", 1)
s = s.replace("  captureHandoffPending = true;", "  captureHandoffPending = false;", 1)
ready_start = s.index("  Promise.resolve(cut.ready).then(info => {", s.index('async function rotateLiveSegment'))
ready_end = s.index("  return true;\n}", ready_start)
s = s[:ready_start] + "  // takeSegment keeps the recognizer running: no restart gap at speaker/question boundaries.\n" + s[ready_end:]

old_nav = '''  const targetQuestionId = all[index]?.question?.id || null;\n  if (isRecording() && targetQuestionId && recordingQuestionId !== targetQuestionId) {\n    moveRecordingToViewedQuestion().catch(error => recordRuntimeWarning('question_capture_transfer_warning', error));\n  }\n  persistSessionLater('question-navigation');'''
new_nav = '''  // Navigation changes only the viewed question. Capture ownership remains explicit until\n  // the interviewer uses the visible transfer action in the capture banner.\n  renderCaptureQuestionContext();\n  persistSessionLater('question-navigation');'''
if old_nav not in s: raise SystemExit('nav auto-transfer block not found')
s = s.replace(old_nav, new_nav, 1)

s = s.replace("    replay.addEventListener('click', () => replayTurnAudio(turn));", "    replay.addEventListener('click', () => replayTurnAudio(turn, replay));", 1)
old_btn = '''    const trackSupported = supportsSystemAudioTrackRecognition();\n    retranscribe.disabled = !turn.audioRef?.recordingId || !trackSupported || systemSpeechCapability.mode === 'unavailable';\n    retranscribe.title = trackSupported\n      ? 'Relancer la transcription système directement depuis cet audio'\n      : 'Retranscription système depuis un audio enregistré non prise en charge sur ce navigateur mobile ou ancien';'''
new_btn = '''    const trackSupported = supportsSystemAudioTrackRecognition();\n    const stableRetranscription = turn.systemRetranscription?.status;\n    retranscribe.textContent = stableRetranscription === 'succeeded' ? '✓ Système' : stableRetranscription === 'failed' ? '× Système' : '↻ Système';\n    retranscribe.disabled = !turn.audioRef?.recordingId || !trackSupported || systemSpeechCapability.mode === 'unavailable' || ['succeeded', 'failed'].includes(stableRetranscription);\n    retranscribe.title = stableRetranscription === 'succeeded'\n      ? 'Retranscription système stabilisée pour cet audio'\n      : stableRetranscription === 'failed'\n        ? 'Tentative système terminée sans texte : correction manuelle disponible'\n        : trackSupported\n          ? 'Transcrire une seule fois cet audio avec le système'\n          : 'Retranscription système depuis un audio enregistré non prise en charge sur ce navigateur mobile ou ancien';'''
if old_btn not in s: raise SystemExit('retranscribe button block not found')
s = s.replace(old_btn, new_btn, 1)
app_path.write_text(s)

# index cache bump
p = Path('offline-interview/index.html'); x = p.read_text().replace('styles.css?v=41.5','styles.css?v=41.6').replace('app.js?v=41.5','app.js?v=41.6'); p.write_text(x)
# sw cache bump
p = Path('offline-interview/sw.js'); x = p.read_text().replace("offline-interview-v41.5","offline-interview-v41.6").replace('styles.css?v=41.5','styles.css?v=41.6').replace('app.js?v=41.5','app.js?v=41.6'); p.write_text(x)

# runtime contract
p = Path('offline-interview/test-runtime-contract.mjs'); x = p.read_text()
x = x.replace("assert.match(navBody, /moveRecordingToViewedQuestion\\(\\)\\.catch/);", "assert.doesNotMatch(navBody, /moveRecordingToViewedQuestion\\(\\)\\.catch/);\nassert.match(navBody, /renderCaptureQuestionContext\\(\\)/);")
x = x.replace("// V41.5: automatic transcription is system-first/system-only; saved audio remains usable when text is absent.", "// V41.5: automatic transcription is system-first/system-only; saved audio remains usable when text is absent.")
insert = """\n// V41.6 field stabilization: explicit capture ownership, gapless semantic boundaries, replay pause, idempotent retranscription.\nassert.match(app, /systemSpeechSession\\?\\.takeSegment/);\nassert.doesNotMatch(app.match(/async function rotateLiveSegment[\\s\\S]*?return true;\\n\\}/)?.[0] || '', /cutSegment\\(/);\nassert.match(app, /L’enregistrement reste sur/);\nassert.match(app, /replayTurnAudio\\(turn, replay\\)/);\nassert.match(app, /activeReplayTurnId === turn.id/);\nassert.match(app, /⏳ Système…/);\nassert.match(app, /systemRetranscription = \\{ audioKey, status: 'succeeded'/);\nassert.match(app, /\\['succeeded', 'failed'\\]\\.includes\\(stableRetranscription\\)/);\n"""
needle = "// Explicit anti-growth budgets. Raising one requires a conscious code-review decision."
x = x.replace(needle, insert + "\n" + needle, 1)
x = x.replace("assert.ok(bytes(app) <= 106_500", "assert.ok(bytes(app) <= 110_000")
x = x.replace("assert.ok(coreBytes <= 207_000", "assert.ok(coreBytes <= 211_000")
x = x.replace("contract: 'offline-interview.runtime-contract.v41.5'", "contract: 'offline-interview.runtime-contract.v41.6'")
p.write_text(x)

# field test
field = {
  "schema":"offline-interview.interview-spec.v1","id":"test-ux-v41-6-field-stabilization","version":"1.0",
  "title":"Test V41.6 — stabilisation terrain","context":"Qualification humaine avant promotion.",
  "objective":"Vérifier ownership de question, frontières locuteur, replay pause et retranscription système stable.","language":"fr-FR","estimatedDurationMinutes":8,
  "participants":[{"id":"P1","name":"Interviewer","role":"interviewer"},{"id":"P2","name":"Testeur","role":"interviewee"}],
  "sections":[{"id":"S1","title":"Stabilisation","questions":[
    {"id":"Q1","label":"Navigation et ownership","text":"Démarrez Testeur sur cette question. Sans arrêter l'enregistrement, ouvrez la question 2. Vérifiez que la question affichée change mais que le bandeau dit clairement que l'enregistrement reste sur la question 1. Cliquez ensuite sur Basculer sur la question 2 et vérifiez seulement alors que l'enregistrement change de question.","intent":"Séparer navigation et propriété de captation.","estimatedMinutes":2,"required":True,"audience":["P2"],"followUps":[]},
    {"id":"Q2","label":"Changements de personne","text":"Pendant une seule captation continue, alternez plusieurs fois Testeur et Interviewer en disant des suites courtes distinctes : alpha bravo charlie ; delta echo foxtrot ; golf hotel india ; juliet kilo lima. Après la fin, vérifiez qu'aucun groupe n'a disparu et qu'aucun groupe n'est attribué à la mauvaise personne.","intent":"Vérifier les frontières sans trou de redémarrage du moteur système.","estimatedMinutes":2,"required":True,"audience":["P1","P2"],"followUps":[]},
    {"id":"Q3","label":"Lecture et pause","text":"Terminez puis choisissez Relire / corriger. Sur une prise audio, cliquez sur ▶ : le bouton doit devenir pause. Cliquez pause puis lecture et vérifiez que l'écoute reprend sans devoir attendre la fin de la piste.","intent":"Qualifier le contrôle lecture/pause.","estimatedMinutes":1,"required":True,"audience":["P2"],"followUps":[]},
    {"id":"Q4","label":"Retranscription stable Windows","text":"Sur Windows Chrome ou Edge récent, cliquez une seule fois sur ↻ Système. Pendant le traitement, le bouton doit afficher clairement qu'il travaille. À la fin il devient ✓ Système ou × Système et ne doit plus pouvoir être relancé. Vérifiez que des clics supplémentaires ne changent plus le texte.","intent":"Une piste audio donne au plus un résultat système stabilisé.","estimatedMinutes":2,"required":True,"audience":["P2"],"followUps":[]},
    {"id":"Q5","label":"Téléphone","text":"Sur téléphone, vérifiez la navigation avec un enregistrement actif, le bandeau de question propriétaire et lecture/pause. Si ↻ Système n'est pas pris en charge, il doit rester indisponible avec une explication claire. Aucun Whisper automatique ne doit démarrer.","intent":"Qualification mobile fail-closed.","estimatedMinutes":1,"required":True,"audience":["P2"],"followUps":[]}
  ]}]
}
Path('offline-interview/test-interviews/interview-test-ux-v41-6.json').write_text(json.dumps(field, ensure_ascii=False, indent=2)+"\n")
